insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '8082bde2-0f27-5735-abb0-76f86826d01e', id, null, 30, '14', 'Apresentar um relatório escrito de, no mínimo, 300 palavras ou oral de 5 minutos sobre a importância da Fruticultura (produção de frutos exigidos nos requisitos dessa especialidade) e referir suas principais características.', '2026-11-01 09:46:10', null from especialidades where codigo = 'AA-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'a950f671-958e-5d15-975f-b52fb66528d7', id, null, 31, '15', 'Visitar uma propriedade rural onde se pratica a fruticultura e elaborar um relatório de, pelo menos, 300 palavras destacando as principais atividades ali desenvolvidas, bem como sobre a sua experiência vivida para o cumprimento dos requisitos desta especialidade.', '2026-11-01 09:46:10', null from especialidades where codigo = 'AA-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
